def solve(payload):
    import ipaddress
    import re
    from urllib.parse import urlsplit
    def canonical(value, origin_only=False):
        if any(ord(ch) <= 32 or ord(ch) >= 127 or ch == "\\" for ch in value):
            return None
        try:
            parts = urlsplit(value)
            if parts.scheme not in ("http", "https") or parts.username is not None or parts.password is not None:
                return None
            if origin_only and (parts.path not in ("", "/") or parts.query or parts.fragment):
                return None
            authority_pattern = r"\[[^\]]+\](?::[0-9]+)?" if parts.netloc.startswith("[") else r"[^:]+(?::[0-9]+)?"
            if not re.fullmatch(authority_pattern, parts.netloc):
                return None
            host = parts.hostname
            if not host or "%" in host:
                return None
            port = parts.port
            if port is not None and not 1 <= port <= 65535:
                return None
            if ":" in host:
                host = "["+ipaddress.IPv6Address(host).compressed+"]"
            else:
                host = host.lower()
                if host.endswith("."):
                    host = host[:-1]
                if not 1 <= len(host) <= 253 or any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", label) for label in host.split(".")):
                    return None
            default = 80 if parts.scheme == "http" else 443
            suffix = "" if port is None or port == default else ":"+str(port)
            return parts.scheme+"://"+host+suffix
        except ValueError:
            return None
    allowed = set()
    for value in payload["allowed_origins"]:
        origin = canonical(value, True)
        if origin is None:
            return {"error": "invalid_origin"}
        allowed.add(origin)
    results = []
    for value in payload["urls"]:
        origin = canonical(value)
        results.append({"origin": origin, "allowed": origin is not None and origin in allowed})
    return {"results": results}
